QUERY_TEXT:
/* cppi::a54bef7f73d291431f71264af7614ee2ae667e1f180d9bcb5548cb3673b63f55 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-26' and business_date <= date '2025-06-26' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::eb39c5b8fcff20070b0e2eb5b915002d4da6bb13aff56b08b1b8f226b4bc286f */
SELECT run_date, outcome, ruleset_id, run_timestamp, run_id, lookback_days, rule_id, evaluation_message, rule, rule_description, rule_name, rule_type, ruleset_version, run_account_id, evaluated_metrics, rule_dimension, database_name, table_name, failed_record_count, failed_percent, file_process_date, raised_exception, total_records_tested, total_pass_count, total_pass_percentage, completion_time, recheck, job_type, group_name, owner_name, frequency, data_source, dataset, dq_source, evaluated_rule
FROM dataops.dq_results where table_name LIKE '%scd%securities' order by file_process_date  desc limit 10

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

